CREATE DATABASE IF NOT EXISTS repair_shop CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE repair_shop;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,full_name VARCHAR(100) NOT NULL,role ENUM('admin','employee') DEFAULT 'employee',status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,phone VARCHAR(50),email VARCHAR(150),address VARCHAR(255),notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE technicians(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,phone VARCHAR(50),specialty VARCHAR(150),salary DECIMAL(12,2) DEFAULT 0,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE repairs(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,technician_id INT NULL,device_type VARCHAR(100),device_model VARCHAR(150),serial_number VARCHAR(150),problem TEXT,diagnosis TEXT,repair_notes TEXT,status ENUM('new','checking','repairing','ready','delivered','cancelled') DEFAULT 'new',estimated_cost DECIMAL(12,2) DEFAULT 0,final_cost DECIMAL(12,2) DEFAULT 0,paid_amount DECIMAL(12,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,delivered_at DATETIME NULL,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE,FOREIGN KEY(technician_id) REFERENCES technicians(id) ON DELETE SET NULL);
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,barcode VARCHAR(100),category VARCHAR(100),purchase_price DECIMAL(12,2) DEFAULT 0,sale_price DECIMAL(12,2) DEFAULT 0,quantity INT DEFAULT 0,min_quantity INT DEFAULT 5,description TEXT,image VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sales(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NULL,user_id INT NULL,total DECIMAL(12,2) DEFAULT 0,paid DECIMAL(12,2) DEFAULT 0,remaining DECIMAL(12,2) DEFAULT 0,payment_method VARCHAR(50) DEFAULT 'cash',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE sale_items(id INT AUTO_INCREMENT PRIMARY KEY,sale_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL,price DECIMAL(12,2) NOT NULL,total DECIMAL(12,2) NOT NULL,FOREIGN KEY(sale_id) REFERENCES sales(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NULL,repair_id INT NULL,sale_id INT NULL,amount DECIMAL(12,2) NOT NULL,payment_method VARCHAR(50) DEFAULT 'cash',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,FOREIGN KEY(repair_id) REFERENCES repairs(id) ON DELETE SET NULL,FOREIGN KEY(sale_id) REFERENCES sales(id) ON DELETE SET NULL);
CREATE TABLE expenses(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,amount DECIMAL(12,2) NOT NULL,description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE permissions(id INT AUTO_INCREMENT PRIMARY KEY,permission_name VARCHAR(100) UNIQUE NOT NULL,description VARCHAR(255));
CREATE TABLE user_permissions(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,permission_id INT NOT NULL,UNIQUE KEY up(user_id,permission_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
